#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        exp >>= 1;
        base = (base * base) % MOD;
    }
    return res;
}

long long choose(long long n, long long k) {
    long long numerator = 1;
    long long denominator = 1;
    for (long long i = n - k + 1; i <= n; i++) {
        numerator = (numerator * i) % MOD;
    }
    for (long long i = 1; i <= k; i++) {
        denominator = (denominator * i) % MOD;
    }
    denominator = power(denominator, MOD - 2);
    return (numerator * denominator) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN;
    long long totalK;
    cin >> totalN >> totalK;
    if (totalK >= totalN) {
        cout << 0 << "\n";
    } else {
        int kVal = (int) totalK;
        int rVal = totalN - kVal;
        std::vector<long long> combs(rVal + 1);
        combs[0] = 1LL;
        long long num = 1LL;
        long long den = 1LL;
        for (int i = 1; i <= rVal; i++) {
            num = (num * (rVal + 1 - i)) % MOD;
            den = (den * i) % MOD;
            combs[i] = (num * power(den, MOD - 2)) % MOD;
        }
        long long result = 0;
        long long flip = 1;
        for (int i = 0; i <= rVal; i++) {
            long long term = power((long long)(rVal - i), (long long)totalN);
            result += term * flip * combs[i];
            result %= MOD;
            flip = -flip;
        }
        result = (result * choose((long long)totalN, (long long)kVal)) % MOD;
        if (kVal > 0) {
            result = (result * 2) % MOD;
        }
        if (result < 0) {
            result += MOD;
        }
        cout << result << "\n";
    }
    return 0;
}
